FILE /etc/nginx/http.d/default.conf
# This is a default site configuration which will simply return 404, preventing
# chance access to any other virtualhost.

server {
	listen 80 default_server;
	listen [::]:80 default_server;

	# Everything is a 404
	location / {
		return 404;
	}

	# You may need this to prevent return 404 recursion.
	location = /404.html {
		internal;
	}
}

command:
set -eu
cat > /etc/nginx/http.d/help.conf <<'ANTRIEB_EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /srv/legacy2/permanent-url-migration;

    location = /manual {
        return 301 /help/$is_args$args;
    }

    location ^~ /manual/ {
        rewrite ^/manual/(.*)$ /help/$1 permanent;
    }

    location = /status.txt {
        try_files /status.txt =404;
    }

    location /help/ {
        try_files $uri $uri/ =404;
    }

    location / {
        return 404;
    }
}
ANTRIEB_EOF
nginx -t
rc-update add nginx default
rc-service nginx start
rc-service nginx status
ss -ltnp | grep ':8080'

